private val Rp = NumberFormat.getCurrencyInstance(Locale("id", "ID")).apply { maximumFractionDigits = 0 }
private fun mMoney(value: Long?): String = Rp.format(value ?: 0L)
private fun JsonObject.mText(vararg keys: String): String = keys.firstNotNullOfOrNull { string(it)?.takeIf(String::isNotBlank) } ?: "-"
private fun JsonObject.mNumber(vararg keys: String): Long = keys.firstNotNullOfOrNull { long(it) } ?: 0L
private fun JsonObject.mItems(): List<JsonObject> = array("items")?.filterIsInstance<JsonObject>().orEmpty()
private fun initials(name: String): String = name.trim().split(" ").filter(String::isNotBlank).take(2).joinToString("") { it.first().uppercase() }.ifBlank { "IC" }

class ModernMainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val session = SessionManager(applicationContext)
        val repo = Repository(ApiClient(session).api)
        setContent {
            val appVm: AppViewModel = viewModel(factory = object : ViewModelProvider.Factory {
                override fun <T : androidx.lifecycle.ViewModel> create(modelClass: Class<T>): T = AppViewModel(session, repo) as T
            })
            IrkopTheme { ModernRoot(appVm, repo) }
        }
    }
}

@Composable private fun ModernRoot(vm: AppViewModel, repo: Repository) {
    val state by vm.state.collectAsState()
    when {
        state.loading -> Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { CircularProgressIndicator() }
        state.user == null -> ModernLogin(state.error, vm::login, vm::clearError)
        else -> ModernScaffold(state.user!!, vm::logout, repo)
    }
}

@Composable private fun ModernLogin(error: String?, login: (String, String) -> Unit, clear: () -> Unit) {
    var username by rememberSaveable { mutableStateOf("") }
    var password by rememberSaveable { mutableStateOf("") }
    Column(Modifier.fillMaxSize().padding(24.dp), verticalArrangement = Arrangement.Center) {
        Box(Modifier.size(72.dp).clip(RoundedCornerShape(22.dp)).background(MaterialTheme.colorScheme.primary), contentAlignment = Alignment.Center) { Icon(Icons.Default.PhoneAndroid, null, tint = MaterialTheme.colorScheme.onPrimary, modifier = Modifier.size(36.dp)) }
        Spacer(Modifier.height(20.dp)); Text("IRKOP CELL", style = MaterialTheme.typography.headlineLarge); Text("POS & Buku Kas Digital", color = MaterialTheme.colorScheme.onSurfaceVariant)
        Spacer(Modifier.height(26.dp)); OutlinedTextField(username, { username = it }, label = { Text("Username") }, leadingIcon = { Icon(Icons.Default.Person, null) }, singleLine = true, modifier = Modifier.fillMaxWidth()); Spacer(Modifier.height(10.dp)); OutlinedTextField(password, { password = it }, label = { Text("Password") }, leadingIcon = { Icon(Icons.Default.Lock, null) }, visualTransformation = PasswordVisualTransformation(), singleLine = true, modifier = Modifier.fillMaxWidth()); Spacer(Modifier.height(18.dp)); Button(onClick = { login(username.trim(), password) }, enabled = username.isNotBlank() && password.isNotBlank(), modifier = Modifier.fillMaxWidth(), shape = MaterialTheme.shapes.medium) { Text("Masuk") }
        if (!error.isNullOrBlank()) { Spacer(Modifier.height(10.dp)); Text(error, color = MaterialTheme.colorScheme.error); LaunchedEffect(error) { clear() } }
    }
}

private data class AppTab(val route: String, val label: String, val icon: androidx.compose.ui.graphics.vector.ImageVector, val enabled: Boolean)
@Composable private fun ModernScaffold(user: UserSession, logout: () -> Unit, repo: Repository) {
    var tab by rememberSaveable { mutableStateOf("dashboard") }
    val tabs = listOf(AppTab("dashboard", "Dashboard", Icons.Default.Home, AuthPolicy.canAccess(user, AuthPolicy.DASHBOARD)), AppTab("transaksi", "Transaksi", Icons.Default.ReceiptLong, AuthPolicy.canAccess(user, AuthPolicy.TRANSAKSI)), AppTab("kasir", "Kasir", Icons.Default.PointOfSale, AuthPolicy.canAccess(user, AuthPolicy.KASIR)), AppTab("laporan", "Laporan", Icons.Default.Assessment, AuthPolicy.canAccess(user, AuthPolicy.LAPORAN)), AppTab("lainnya", "Lainnya", Icons.Default.MoreHoriz, true))
    if (tabs.none { it.route == tab && it.enabled }) tab = tabs.firstOrNull { it.enabled }?.route ?: "lainnya"
    Scaffold(containerColor = MaterialTheme.colorScheme.background, topBar = { if (tab == "dashboard") TopAppBar(title = { Column { Text("IRKOP CELL", style = MaterialTheme.typography.titleLarge); Text(user.nama.ifBlank { user.username }, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant) } }, navigationIcon = { IconButton(onClick = { tab = "lainnya" }) { Icon(Icons.Default.Menu, "Menu") } }, actions = { IconButton(onClick = {}) { Icon(Icons.Default.NotificationsNone, "Notifikasi") }; IconButton(onClick = logout) { Icon(Icons.Default.Logout, "Keluar") } }) }, bottomBar = { NavigationBar { tabs.forEach { item -> NavigationBarItem(selected = tab == item.route, enabled = item.enabled, onClick = { if (item.enabled) tab = item.route }, icon = { Icon(item.icon, item.label) }, label = { Text(item.label) }) } } }) { padding -> Box(Modifier.fillMaxSize().padding(padding)) { when (tab) { "dashboard" -> ModernDashboard(repo, { tab = "transaksi" }, { tab = "kasir" }, { tab = "lainnya" }, { tab = "laporan" }); "transaksi" -> ModernTransactions(repo); "kasir" -> ModernCashier(repo); "laporan" -> ModernReport(repo); else -> ParityExtrasScreen(user, repo) } } }
}

@Composable private fun ModernDashboard(repo: Repository, goTransaction: () -> Unit, goCashier: () -> Unit, goOther: () -> Unit, goReport: () -> Unit) {
    val scope = rememberCoroutineScope(); var loading by remember { mutableStateOf(true) }; var error by remember { mutableStateOf<String?>(null) }; var transaksi by remember { mutableStateOf<JsonObject?>(null) }; var kasbon by remember { mutableStateOf<JsonObject?>(null) }; var pelanggan by remember { mutableStateOf<JsonObject?>(null) }; var kasir by remember { mutableStateOf<JsonObject?>(null) }
    suspend fun load() { loading = true; error = null; val results = coroutineScope { listOf(async { runCatching { repo.transaksi(tanggal = LocalDate.now().toString()) }.getOrNull() }, async { runCatching { repo.kasbon() }.getOrNull() }, async { runCatching { repo.pelanggan() }.getOrNull() }, async { runCatching { repo.kasirCurrent() }.getOrNull() }).awaitAll() }; transaksi=results[0]; kasbon=results[1]; pelanggan=results[2]; kasir=results[3]; if(results.all{it==null}) error="Dashboard belum dapat memuat data."; loading=false }
    LaunchedEffect(Unit) { load() }
    val transactionRows=transaksi?.mItems().orEmpty(); val omzet=transaksi?.mNumber("total_nilai","total_omzet","omzet")?:transaksi?.obj("ringkasan")?.mNumber("omzet","total_omzet")?:transactionRows.sumOf{it.mNumber("total","nominal","grand_total")}; val count=transaksi?.mNumber("total_items","jumlah_transaksi","transaksi")?.takeIf{it>0}?:transactionRows.size.toLong(); val activeKasbon=kasbon?.mItems()?.count{it.mText("status","status_pembayaran").lowercase() in listOf("belum_lunas","belum lunas","aktif")}?:0; val customerCount=pelanggan?.mNumber("total_items","jumlah","total_pelanggan")?.takeIf{it>0}?:pelanggan?.mItems()?.size?.toLong()?:0L
    LazyColumn(Modifier.fillMaxSize().padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(16.dp),contentPadding=PaddingValues(top=12.dp,bottom=24.dp)){item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf("Pelanggan","Kasbon","Service HP","Akun Uang").forEachIndexed{i,label->FilterChip(selected=i==0,onClick={},label={Text(label)})}}};item{GradientSummaryCard{Text("Ringkasan Hari Ini",style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(12.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){ModernStat("Pendapatan",mMoney(omzet),"↑ 0%",Icons.Default.TrendingUp,Modifier.weight(1f));ModernStat("Transaksi",count.toString(),"↑ 0%",Icons.Default.ReceiptLong,Modifier.weight(1f))};Spacer(Modifier.height(8.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){ModernStat("Kasbon",activeKasbon.toString(),"↓ 0%",Icons.Default.AccountBalanceWallet,Modifier.weight(1f));ModernStat("Pelanggan",customerCount.toString(),"↑ 0%",Icons.Default.People,Modifier.weight(1f))}}};item{Text("Menu Cepat",style=MaterialTheme.typography.titleLarge)};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){QuickAction("Transaksi",Icons.Default.ReceiptLong,goTransaction);QuickAction("Kasir",Icons.Default.PointOfSale,goCashier);QuickAction("Kasbon",Icons.Default.AccountBalanceWallet,goOther);QuickAction("Laporan",Icons.Default.Assessment,goReport);QuickAction("Stok",Icons.Default.Inventory2,goOther)}};item{Text("Aktivitas Terakhir",style=MaterialTheme.typography.titleLarge)};if(loading)item{Box(Modifier.fillMaxWidth().padding(24.dp),contentAlignment=Alignment.Center){CircularProgressIndicator()}}else if(transactionRows.isEmpty())item{ModernEmpty("Belum ada transaksi hari ini","Transaksi baru akan tampil di sini.")}else items(transactionRows.take(8)){row->ModernActivity(row)};error?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}};kasir?.let{item{Text("Status kasir: ${it.mText("status")}",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}
}

