private data class CartLine(val product:JsonObject,val qty:Int)
private fun addLine(cart:List<CartLine>,product:JsonObject)=cart.firstOrNull{it.product.mText("id")==product.mText("id")}?.let{cart.map{line->if(line.product.mText("id")==product.mText("id"))line.copy(qty=line.qty+1)else line}}?:cart+CartLine(product,1)
private fun removeLine(cart:List<CartLine>,id:String)=cart.mapNotNull{if(it.product.mText("id")!=id)it else it.copy(qty=it.qty-1).takeIf{line->line.qty>0}}

