.Default.Add,"Tambah")}}}};item{Card(Modifier.fillMaxWidth(),shape=MaterialTheme.shapes.medium){Column(Modifier.padding(16.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Subtotal");Text(mMoney(total))};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Diskon");Text(mMoney(0))};HorizontalDivider(Modifier.padding(vertical=8.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Total",style=MaterialTheme.typography.titleLarge);Text(mMoney(total),style=MaterialTheme.typography.titleLarge)}}}}};item{Text("Produk",style=MaterialTheme.typography.titleLarge)};items(shown.take(30)){product->Card(onClick={cart=addLine(cart,product)},modifier=Modifier.fillMaxWidth(),shape=MaterialTheme.shapes.medium){Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(40.dp).clip(RoundedCornerShape(12.dp)).background(MaterialTheme.colorScheme.primary.copy(alpha=.12f)),contentAlignment=Alignment.Center){Icon(Icons.Default.Inventory2,null,tint=MaterialTheme.colorScheme.primary)};Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(product.mText("nama"),style=MaterialTheme.typography.titleMedium);Text("Stok ${product.mNumber("stok")}",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};Text(mMoney(product.mNumber("harga","harga_jual")),style=MaterialTheme.typography.titleMedium)}}};item{Text("Metode Pembayaran",style=MaterialTheme.typography.titleLarge)};item{Row(horizontalArrangement=Arrangement.spacedBy(7.dp)){listOf("tunai","transfer","bon","lainnya").forEach{value->FilterChip(selected=method==value,onClick={method=value},label={Text(value.replaceFirstChar{it.uppercase()})})}}};item{OutlinedTextField(customer,{customer=it.filter(Char::isDigit)},label={Text("Pelanggan ID untuk Kasbon")},singleLine=true,modifier=Modifier.fillMaxWidth())};item{Button(onClick={if(method=="bon"&&customer.toLongOrNull()==null){message="Pelanggan wajib untuk kasbon."}else{busy=true;scope.launch{runCatching{repo.createTransaksi(buildJsonObject{putJsonArray("items"){cart.forEach{line->add(buildJsonObject{put("produk_id",line.product["id"]?:JsonNull);put("qty",line.qty)})}};put("metode_bayar",if(method=="lainnya")"cash_tunai"else method);customer.toLongOrNull()?.let{put("pelanggan_id",it)}})}.onSuccess{cart=emptyList();message="Pembayaran berhasil disimpan."}.onFailure{message=ApiError.message(it)};busy=false}}},enabled=cart.isNotEmpty()&&total>0&&!busy,modifier=Modifier.fillMaxWidth(),shape=MaterialTheme.shapes.medium){Text(if(busy)"Memproses…"else"Bayar ${mMoney(total)}")};message?.let{item{Text(it,color=if(it.contains("berhasil"))MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error)}}}
}

@Composable private fun ModernCheckoutDialog(repo:Repository,onDone:()->Unit,onCancel:()->Unit){val scope=rememberCoroutineScope();var products by remember{mutableStateOf(emptyList<JsonObject>())};var cart by remember{mutableStateOf(emptyList<CartLine>())};var method by remember{mutableStateOf("tunai")};var customer by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};var error by remember{mutableStateOf<String?>(null)};LaunchedEffect(Unit){runCatching{repo.produk()}.onSuccess{products=it.mItems()}.onFailure{error=ApiError.message(it)}};val total=cart.sumOf{it.product.mNumber("harga","harga_jual")*it.qty};AlertDialog(onDismissRequest=onCancel,title={Text("Transaksi Baru")},text={LazyColumn(Modifier.heightIn(max=520.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){if(cart.isEmpty())item{ModernEmpty("Keranjang kosong","Pilih produk di bawah.")}else items(cart){line->Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text(line.product.mText("nama"),Modifier.weight(1f));Text("${line.qty}×");IconButton(onClick={cart=removeLine(cart,line.product.mText("id"))}){Icon(Icons.Default.Remove,"Kurangi")};IconButton(onClick={cart=addLine(cart,line.product)}){Icon(Icons.Default.Add,"Tambah")}}};items(products.take(20)){product->Card(onClick={cart=addLine(cart,product)},modifier=Modifier.fillMaxWidth()){Row(Modifier.padding(9.dp)){Text(product.mText("nama"),Modifier.weight(1f));Text(mMoney(product.mNumber("harga","harga_jual")))}}};item{OutlinedTextField(customer,{customer=it.filter(Char::isDigit)},label={Text("Pelanggan ID")},modifier=Modifier.fillMaxWidth())};item{Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){listOf("tunai","transfer","bon","cash_tunai").forEach{value->FilterChip(selected=method==value,onClick={method=value},label={Text(value.replace('_',' ').replaceFirstChar{it.uppercase()})})}}};item{Text("Total ${mMoney(total)}",style=MaterialTheme.typography.titleLarge)};error?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}}}},confirmButton={Button(onClick={if(method=="bon"&&customer.toLongOrNull()==null){error="Pelanggan wajib untuk kasbon."}else{busy=true;scope.launch{runCatching{repo.createTransaksi(buildJsonObject{putJsonArray("items"){cart.forEach{line->add(buildJsonObject{put("produk_id",line.product["id"]?:JsonNull);put("qty",line.qty)})}};put("metode_bayar",method);customer.toLongOrNull()?.let{put("pelanggan_id",it)}})}.onSuccess{onDone()}.onFailure{error=ApiError.message(it)};busy=false}}},enabled=cart.isNotEmpty()&&total>0&&!busy){Text(if(busy)"Memproses…"else"Simpan")}},dismissButton={TextButton(onClick=onCancel){Text("Batal")}})}

@Composable private fun ModernReport(repo:Repository){val scope=rememberCoroutineScope();var month by remember{mutableStateOf(LocalDate.now().toString().substring(0,7))};var data by remember{mutableStateOf<JsonObject?>(null)};var loading by remember{mutableStateOf(true)};var error by remember{mutableStateOf<String?>(null)};suspend fun load(){loading=true;runCatching{repo.laporanBulan(month)}.onSuccess{data=it}.onFailure{error=ApiError.message(it)};loading=false};LaunchedEffect(Unit){load()};val summary=data?.obj("summary")?:data?.obj("ringkasan")?:data;val series=data?.array("harian")?.filterIsInstance<JsonObject>()?:data?.array("daily")?.filterIsInstance<JsonObject>().orEmpty();LazyColumn(Modifier.fillMaxSize().padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(12.dp),contentPadding=PaddingValues(top=12.dp,bottom=24.dp)){item{Row(verticalAlignment=Alignment.CenterVertically){Text("Laporan",style=MaterialTheme.typography.headlineMedium,modifier=Modifier.weight(1f));Icon(Icons.Default.CalendarMonth,"Tanggal")}};item{Row(horizontalArrangement=Arrangement.spacedBy(7.dp)){listOf("Ringkasan","Penjualan","Kasbon","Produk").forEachIndexed{i,label->FilterChip(selected=i==0,onClick={},label={Text(label)})}}};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp),verticalAlignment=Alignment.CenterVertically){OutlinedTextField(month,{month=it},label={Text("Periode YYYY-MM")},modifier=Modifier.weight(1f),singleLine=true);Button(onClick={scope.launch{load()}}){Text("Muat")}}};if(loading)item{Box(Modifier.fillMaxWidth().padding(24.dp),contentAlignment=Alignment.Center){CircularProgressIndicator()}}else{item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){ReportMetric("Total Pendapatan",mMoney(summary?.mNumber("omzet","total_omzet")),Modifier.weight(1f));ReportMetric("Total Transaksi",summary?.mNumber("jumlah_transaksi","transaksi","total_items").toString(),Modifier.weight(1f))}};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){ReportMetric("Total Kasbon",mMoney(summary?.mNumber("kasbon","kasbon_aktif")),Modifier.weight(1f));ReportMetric("Total Pelanggan",summary?.mNumber("pelanggan","jumlah_pelanggan").toString(),Modifier.weight(1f))}};item{RevenueChart(series)};item{ReportFinance(summary)};data?.array("kategori")?.filterIsInstance<JsonObject>()?.takeIf{it.isNotEmpty()}?.let{rows->item{ReportRows("Rekap Kategori",rows)}};data?.array("best_selling")?.filterIsInstance<JsonObject>()?.takeIf{it.isNotEmpty()}?.let{rows->item{ReportRows("Penjualan Terlaris",rows)}}};error?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}}}}
@Composable private fun ReportMetric(label:String,value:String,modifier:Modifier){Card(modifier,shape=MaterialTheme.shapes.medium){Column(Modifier.padding(14.dp)){Text(label,style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant);Text(value,style=MaterialTheme.typography.titleLarge);Text("Periode terpilih",style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.primary)}}}
@Composable private fun RevenueChart(rows:List<JsonObject>){Card(Modifier.fillMaxWidth(),shape=MaterialTheme.shapes.medium){Column(Modifier.padding(16.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Grafik Pendapatan",style=MaterialTheme.typography.titleMedium);AssistChip(onClick={},label={Text("Per Hari")})};Spacer(Modifier.height(10.dp));if(rows.isEmpty())Text("Data harian belum tersedia dari API.",color=MaterialTheme.colorScheme.onSurfaceVariant)else{val values=rows.map{it.mNumber("omzet","pendapatan","total","nominal")};Canvas(Modifier.fillMaxWidth().height(175.dp)){val max=(values.maxOrNull()?:1L).coerceAtLeast(1L).toFloat();val step=if(values.size<2)size.width else size.width/(values.size-1);val path=Path();values.forEachIndexed{i,v->{val x=step*i;val y=size.height-v.toFloat()/max*size.height;if(i==0)path.moveTo(x,y)else path.lineTo(x,y);drawCircle(MaterialTheme.colorScheme.primary,5f,androidx.compose.ui.geometry.Offset(x,y))}};drawPath(path,MaterialTheme.colorScheme.primary,style=Stroke(5f,cap=StrokeCap.Round))}}}}}
@Composable private fun ReportFinance(summary:JsonObject?){Card(Modifier.fillMaxWidth(),shape=MaterialTheme.shapes.medium){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Ringkasan Keuangan",style=MaterialTheme.typography.titleMedium);listOf("Omzet" to summary?.mNumber("omzet","total_omzet"),"Laba" to summary?.mNumber("laba","total_laba"),"Pengeluaran" to summary?.mNumber("pengeluaran","total_pengeluaran"),"Kasbon" to summary?.mNumber("kasbon","kasbon_aktif"),"Net" to summary?.mNumber("net","laba_bersih")).forEach{(label,value)->Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(label);Text(mMoney(value))}}}}}
@Composable private fun ReportRows(title:String,rows:List<JsonObject>){Card(Modifier.fillMaxWidth(),shape=MaterialTheme.shapes.medium){Column(Modifier.padding(16.dp)){Text(title,style=MaterialTheme.typography.titleMedium);rows.take(10).forEachIndexed{i,row->Row(Modifier.fillMaxWidth().padding(vertical=7.dp),verticalAlignment=Alignment.CenterVertically){Text("${i+1}",modifier=Modifier.width(28.dp),color=MaterialTheme.colorScheme.primary);Text(row.mText("nama","kategori","nama_kategori"),Modifier.weight(1f));Text(mMoney(row.mNumber("omzet","total","nominal")))}}}}}
